insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Avocado', 'fat', 160, 2.0, 8.5, 14.7, 6.7, 110, false, '{"content_hash": "1ed5a9a980749701890f2900e4d2765f", "portion_state": "unspecified", "quotes": ["Avocado is the rare food that is simultaneously a fat source, a fibre source, and an anti-inflammatory \u2014 it does three jobs at once."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **14.7g fat / 100g (monounsaturated)** \u00b7 **6.7g fibre / 100g** \u00b7 **GI: 15** \u00b7 **Mitochondrial benefit: High**\n The rare food that simultaneously delivers fat, fibre, and anti-inflammatory compounds \u2014 doing three jobs at once.", "tags": 0, "food_category": "fat", "calories_per_100g": 160, "protein_per_100g": 2.0, "carbs_per_100g": 8.5, "sugar_per_100g": 0.7, "added_sugar": false, "fat_per_100g": 14.7, "saturated_fat_per_100g": 2.1, "fibre_per_100g": 6.7, "cholesterol_per_100g": 0, "omega3_per_100g_mg": 110, "iron_per_100g": 0.6, "zinc_per_100g": 0.6, "magnesium_per_100g": 29, "potassium_per_100g": 485, "sodium_per_100g": 7, "selenium_per_100g_\u00b5g": 0.4, "choline_per_100g_mg": 14, "vitamin_c_per_100g_mg": 10, "vitamin_d_per_100g_iu": 0, "vitamin_b12_per_100g_\u00b5g": 0, "complete_protein": false, "leucine_per_100g": 0.18, "antioxidant_level": "moderate", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "g", "serving_unit_g": 1, "typical_serving": "\u00bd avocado (100g)", "typical_serving_g": 100, "glycaemic_index": 15, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "\u00bd small (75g)", "calories": "120", "protein": "11.0g", "fat": "1.4g"}, {"portion": "\u00bd medium (100g)", "calories": "160", "protein": "14.7g", "fat": "1.8g"}, {"portion": "\u00be medium (150g)", "calories": "240", "protein": "22.1g", "fat": "2.7g"}, {"portion": "1 whole (200g)", "calories": "320", "protein": "29.4g", "fat": "3.6g"}], "food_synergies": [{"paired_with": "Fat Type", "synergy": "Per 100g", "mechanism": "Properties"}, {"paired_with": "Oleic acid (monounsaturated)", "synergy": "~10g", "mechanism": "Anti-inflammatory; stable; integrates into cell membranes without oxidative stress"}, {"paired_with": "Palmitic acid (saturated)", "synergy": "~2.1g", "mechanism": "Neutral to slightly pro-inflammatory at high intake; well within safe range here"}, {"paired_with": "Linoleic acid (omega-6)", "synergy": "~1.7g", "mechanism": "Low relative to total fat \u2014 not a seed-oil omega-6 concern"}, {"paired_with": "Alpha-linolenic acid (omega-3)", "synergy": "~0.11g", "mechanism": "ALA; minimal EPA/DHA conversion"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs", "synergy": "Fat-soluble vitamin absorption", "mechanism": "Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 fat must be present for these vitamins to absorb; co-ingestion substantially increases their bioavailability"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Polyphenol bioavailability", "mechanism": "Avocado fat dramatically increases the absorption of blueberries'' fat-soluble phytonutrients (beta-carotene, lutein, zeaxanthin); one of the best-evidenced food pairings for nutrient bioavailability"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Anti-inflammatory fat synergy", "mechanism": "Monounsaturated fat (avocado) + EPA/DHA (salmon) together cover the full anti-inflammatory lipid spectrum; zero glucose impact; complementary fat profiles with no overlapping risks"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast", "synergy": "Satiety extension", "mechanism": "Fat slows gastric emptying and prolongs satiety from lean protein; potassium from avocado supports muscle recovery and electrolyte balance after training"}], "dosage_and_timing_guidance": "> [!info] Calorie density is the main consideration\n> **Optimal per meal: \u00bd avocado (75\u2013100g)**\n> - Provides 120\u2013160 calories, 5\u20136.7g fibre, and the full micronutrient benefit\n> - A whole avocado (200g) = ~320 calories, predominantly fat \u2014 appropriate on higher-calorie days or as the primary fat source for a meal\n>\n> **No cholesterol** \u2014 avocado contains no dietary cholesterol whatsoever. Saturated fat is low (2.1g/100g) \u2014 the primary fat is oleic acid, which does not raise LDL meaningfully and may improve the LDL-to-HDL ratio.\n>\n> **No upper limit concern** beyond total calorie budget. Unlike seed oils, avocado fat does not carry oxidative stress, pro-inflammatory omega-6 load, or processing-related compounds.\n>\n> **Ripening:** avocados ripen at room temperature (2\u20135 days from firm). Refrigerate once ripe to extend by 2\u20133 days. The fat profile shifts slightly toward more monounsaturated fat as the fruit ripens \u2014 eat at peak ripeness.\n\n---", "meal_ideas": "Sliced over chicken or salmon \u00b7 Mashed alongside eggs \u00b7 As the fat source in a salad in place of dressing \u00b7 With blueberries as a snack (fat enhances polyphenol absorption)\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]]\n\n---", "good_energy_relevance": "Avocado is one of three foods in the vault (alongside oats and blueberries) that contributes meaningfully to the 50g/day fibre target \u2014 100g provides 6.7g fibre, the highest of any commonly eaten fatty food. The oleic acid integrates into mitochondrial membranes without the oxidative stress that polyunsaturated seed oils generate. The fat content makes avocado one of the most effective glucose-blunting additions to any meal.\n\n**Good Energy daily targets contribution (per 100g):**\n- Fibre: 6.7g of 50g target (13%)\n- Omega-3: 110mg of 2,000mg target (ALA, minimal)\n- Antioxidants: moderate (vitamin E, lutein, zeaxanthin, glutathione \u2014 richest fruit source of glutathione)\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Banana', 'carb', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "012b1fd3699dc97df71171e8bb9f35ef", "portion_state": "unspecified", "quotes": ["calories_per_unit: 105\nprotein_per_unit_g: 1.3\ncarbs_per_unit_g: 27\nfat_per_unit_g: 0.4\nfiber_per_unit_g: 3.1\nsugar_per_unit_g: 14\nprocessing_level:"], "nutrient": "Amount", "calcium": 5.9, "iron": 0.3, "potassium": 422, "sodium": 1.2, "tags": 0, "food_category": "carb", "source": "notion", "notion_category": "Carb", "serving_unit": "1 medium banana", "calories_per_unit": 105, "protein_per_unit_g": 1.3, "carbs_per_unit_g": 27, "fat_per_unit_g": 0.4, "fiber_per_unit_g": 3.1, "sugar_per_unit_g": 14, "processing_level": "Whole/Unprocessed", "fermented": false}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Black Beans', 'carb', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "de961385f4ddff2c378530e5a105f1bd", "portion_state": "unspecified", "quotes": ["calories_per_unit: 120\nprotein_per_unit_g: 8\ncarbs_per_unit_g: 22\nfat_per_unit_g: 0.4\nfiber_per_unit_g: 9\nsugar_per_unit_g: 0\nprocessing_level:"], "nutrient": "Amount", "calcium": 3.5, "potassium": 50, "sodium": 125, "tags": 0, "food_category": "carb", "source": "notion", "notion_category": "Carb", "serving_unit": "1/2 cup", "calories_per_unit": 120, "protein_per_unit_g": 8, "carbs_per_unit_g": 22, "fat_per_unit_g": 0.4, "fiber_per_unit_g": 9, "sugar_per_unit_g": 0, "processing_level": "Minimally Processed", "fermented": false}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Blueberries', 'fruit', 57, 0.7, 14.5, 0.3, 2.4, 58, false, '{"content_hash": "d949f9480fa8f9ba8e31935dc891734a", "portion_state": "unspecified", "quotes": ["Blueberries are the most studied berry for mitochondrial and cognitive health. The anthocyanins cross the blood-brain barrier \u2014 they are feeding your neurons directly."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **Anthocyanins: ~165mg / 100g** \u00b7 **GI: 53** \u00b7 **Mitochondrial benefit: High**\n The highest-priority fruit in the Good Energy framework \u2014 one of few foods that directly activates mitochondrial biogenesis via PGC-1\u03b1.", "tags": 0, "food_category": "fruit", "calories_per_100g": 57, "protein_per_100g": 0.7, "carbs_per_100g": 14.5, "sugar_per_100g": 9.96, "added_sugar": false, "fat_per_100g": 0.3, "saturated_fat_per_100g": 0.0, "fibre_per_100g": 2.4, "cholesterol_per_100g": 0, "omega3_per_100g_mg": 58, "iron_per_100g": 0.3, "zinc_per_100g": 0.2, "magnesium_per_100g": 6, "potassium_per_100g": 77, "sodium_per_100g": 1, "selenium_per_100g_\u00b5g": 0.1, "choline_per_100g_mg": 6, "vitamin_c_per_100g_mg": 9.7, "vitamin_d_per_100g_iu": 0, "vitamin_b12_per_100g_\u00b5g": 0, "complete_protein": false, "leucine_per_100g": 0.07, "antioxidant_level": "high", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "g", "serving_unit_g": 1, "typical_serving": "80g", "typical_serving_g": 80, "glycaemic_index": 53, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "80g", "calories": "46", "protein": "11.6g", "fat": "8.0g"}, {"portion": "100g", "calories": "57", "protein": "14.5g", "fat": "9.96g"}, {"portion": "150g", "calories": "86", "protein": "21.8g", "fat": "14.9g"}], "food_synergies": [{"paired_with": "Compound", "synergy": "Per 100g", "mechanism": "Key Actions"}, {"paired_with": "Total anthocyanins", "synergy": "~165mg", "mechanism": "PGC-1\u03b1 activation; anti-inflammatory; neuroprotective"}, {"paired_with": "Quercetin", "synergy": "~7.7mg", "mechanism": "Anti-inflammatory; antiviral; mast cell stabiliser"}, {"paired_with": "Myricetin", "synergy": "~5.3mg", "mechanism": "Anti-inflammatory; anticancer; neuroprotective"}, {"paired_with": "Chlorogenic acid", "synergy": "~9.8mg", "mechanism": "Anti-glycaemic; antioxidant; liver protective"}, {"paired_with": "Pterostilbene", "synergy": "trace", "mechanism": "Resveratrol analogue; higher bioavailability; epigenetic effects"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble phytonutrient absorption", "mechanism": "Avocado''s monounsaturated fat significantly increases bioavailability of blueberries'' fat-soluble polyphenols (beta-carotene, lutein); the absorption of polyphenols generally improves substantially when co-ingested with dietary fat"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Double anti-glycaemic effect", "mechanism": "Beta-glucan (oats) + anthocyanins (blueberries) independently blunt glucose absorption; together the effect is additive; the combination is one of the most evidence-backed breakfast choices for metabolic health"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Brain health synergy", "mechanism": "DHA (salmon) provides structural substrate for neuronal membranes while anthocyanins (blueberries) reduce neuroinflammation and stimulate BDNF \u2014 synergistic for neuroplasticity and cognitive function"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs", "synergy": "Post-training recovery pair", "mechanism": "Anthocyanins reduce exercise-induced oxidative stress; egg protein and leucine drive muscle protein synthesis \u2014 a complementary recovery combination"}], "dosage_and_timing_guidance": "> [!info] Optimal range and practical notes\n> **Optimal: 80\u2013150g per day**\n> - Below 80g: anthocyanin dose falls below levels used in most cognitive and mitochondrial benefit studies\n> - 80\u2013150g is the functional range for polyphenol benefit without excessive natural sugar load\n> - Above 150g: natural sugars accumulate (9.96g sugar per 100g); diminishing returns on antioxidant benefit per calorie\n>\n> **Wild blueberries:** 2\u20133\u00d7 higher anthocyanin content than cultivated (smaller berries, more skin per gram, deeper colour). Specifically superior for cognitive and mitochondrial applications if available.\n>\n> **Frozen = equally nutritious:** blueberries are frozen at peak ripeness, which preserves anthocyanin content. Out-of-season fresh blueberries are often lower in anthocyanins than frozen. No meaningful nutritional reason to prefer fresh unless in season.\n>\n> **No upper limit concern** for healthy individuals. Blueberries are essentially a free food from a calorie and glycaemic standpoint \u2014 the natural sugar is buffered by fibre and by the anti-glycaemic effect of the anthocyanins themselves.\n\n---", "meal_ideas": "With oats at breakfast \u00b7 Mixed into Greek yogurt \u00b7 As a post-training snack with eggs \u00b7 Frozen blueberries are equally effective \u2014 often preferred for year-round consistency\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]]", "good_energy_relevance": "Despite containing natural sugars (9.96g/100g), blueberries have a moderate GI (53) and a meaningful anti-glycaemic effect \u2014 their anthocyanins inhibit alpha-glucosidase (the enzyme that breaks down complex carbohydrates into glucose), independently reducing post-meal glucose. Long-term studies show blueberry consumption improves insulin sensitivity. The PGC-1\u03b1 activation is the direct mitochondrial link \u2014 making blueberries one of the few foods that supports all three of Means'' primary targets simultaneously: glucose management, mitochondrial health, and antioxidant protection.\n\n**Good Energy daily targets contribution (per 80g):**\n- Fibre: 1.9g of 50g target (4%)\n- Omega-3: 46mg of 2,000mg target (ALA, trace)\n- Antioxidants: high (anthocyanins, quercetin, chlorogenic acid)\n- Probiotics: none (but polyphenols act as prebiotics \u2014 selectively feeding beneficial gut bacteria)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Broccoli', 'produce', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "36f4d3051ce6a99306c0f58ef0d0d49f", "portion_state": "cooked", "quotes": ["1 cup cooked (assumed)"], "tags": 0, "food_category": "produce", "source": "notion", "notion_category": "Produce", "serving_unit": "1 cup cooked (assumed)", "calories_per_unit": 55, "protein_per_unit_g": 3.7, "carbs_per_unit_g": 11.2, "fat_per_unit_g": 0.6, "sugar_per_unit_g": 2, "processing_level": "Whole/Unprocessed", "fermented": false}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Chia Seeds', 'seed', 486, 16.5, 42.1, 30.7, 34.4, 17830, false, '{"content_hash": "5be887d0a8297cb21093e3105cdccf21", "portion_state": "raw_dry", "quotes": ["Chia seeds are a remarkable food \u2014 two tablespoons delivers more fibre than most people eat in an entire day, with virtually no glucose impact."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **34.4g fibre / 100g** \u00b7 **17,830mg ALA omega-3 / 100g** \u00b7 **GI: 1** \u00b7 **Mitochondrial benefit: High**\n The highest-fibre food in the vault \u2014 and the most concentrated plant source of omega-3, though conversion to EPA/DHA is limited.", "tags": 0, "food_category": "seed", "calories_per_100g": 486, "protein_per_100g": 16.5, "carbs_per_100g": 42.1, "sugar_per_100g": 0.0, "added_sugar": false, "fat_per_100g": 30.7, "saturated_fat_per_100g": 3.3, "fibre_per_100g": 34.4, "cholesterol_per_100g": 0, "omega3_per_100g_mg": 17830, "iron_per_100g": 7.7, "zinc_per_100g": 4.6, "magnesium_per_100g": 335, "potassium_per_100g": 407, "sodium_per_100g": 16, "selenium_per_100g_\u00b5g": 55, "choline_per_100g_mg": 0, "vitamin_c_per_100g_mg": 1.6, "vitamin_d_per_100g_iu": 0, "vitamin_b12_per_100g_\u00b5g": 0, "complete_protein": false, "leucine_per_100g": 1.37, "antioxidant_level": "moderate", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "tablespoon", "serving_unit_g": 12, "typical_serving": "2 tablespoons (24g)", "typical_serving_g": 24, "glycaemic_index": 1, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "1 tbsp (12g)", "calories": "58", "protein": "4.1g", "fat": "0.9g"}, {"portion": "2 tbsp / 24g (typical)", "calories": "117", "protein": "8.3g", "fat": "1.8g"}, {"portion": "40g", "calories": "194", "protein": "13.8g", "fat": "3.1g"}], "food_synergies": [{"paired_with": "Fat Type", "synergy": "Per 100g", "mechanism": "Properties"}, {"paired_with": "ALA (omega-3)", "synergy": "~17.8g", "mechanism": "Plant-based omega-3; highest of any common food; converts to EPA/DHA at ~5\u201310% efficiency"}, {"paired_with": "Linoleic acid (omega-6)", "synergy": "~5.8g", "mechanism": "Omega-6 content is lower relative to omega-3 than almost any plant food; omega-6:omega-3 ratio ~0.3:1 \u2014 exceptional"}, {"paired_with": "Palmitic acid (saturated)", "synergy": "~3.3g", "mechanism": "Neutral at this intake level"}, {"paired_with": "Fibre Type", "synergy": "Per 100g", "mechanism": "Role"}, {"paired_with": "Soluble (mucilaginous)", "synergy": "~14\u201316g", "mechanism": "Forms a thick gel when wet; slows gastric emptying; dramatically blunts glucose absorption; feeds gut bacteria"}, {"paired_with": "Insoluble", "synergy": "~18\u201320g", "mechanism": "Increases stool bulk; feeds different microbial populations"}, {"paired_with": "**Total**", "synergy": "**34.4g**", "mechanism": "**69% of the Good Energy 50g/day target in 100g \u2014 highest of any common food**"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt", "synergy": "Synbiotic (prebiotic + probiotic)", "mechanism": "Chia''s soluble fibre feeds the live bacterial cultures in Greek yogurt \u2014 creating a highly gut-optimised combination; also dramatically increases satiety of the yogurt"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Fibre amplification", "mechanism": "Combining chia and oats in one meal (overnight oats) pushes the total fibre well above 15g per meal \u2014 one of the most effective single-meal gut microbiome inputs"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Antioxidant + prebiotic", "mechanism": "Blueberry polyphenols and chia fibre together provide both prebiotic substrate and antioxidant signalling to the gut microbiome"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Omega-3 complementarity", "mechanism": "Chia provides ALA (structural precursor); salmon provides EPA+DHA (active forms) \u2014 together they cover both plant and marine omega-3 pathways"}], "dosage_and_timing_guidance": "> [!info] Small volume, high impact\n> **Optimal: 2\u20133 tablespoons (24\u201336g) per day**\n> - 2 tablespoons: 8.3g fibre, 4,279mg ALA \u2014 a meaningful daily contribution\n> - 3 tablespoons: 12.4g fibre \u2014 covers ~25% of the 50g/day target alone\n>\n> **Hydration:** chia seeds absorb up to 12\u00d7 their weight in water. Consuming dry chia seeds without adequate liquid can cause an uncomfortable gel mass in the gut. Always soak in liquid for at least 10\u201315 minutes, or mix into yogurt, oats, or a smoothie.\n>\n> **Introducing gradually:** the very high fibre content can cause gas and bloating if intake jumps suddenly. Build up from 1 tablespoon over 1\u20132 weeks.\n>\n> **No upper limit concern** from a toxicity standpoint, but above 4\u20135 tablespoons the calorie contribution (486 cal/100g) becomes significant \u2014 chia is calorie-dense by weight.\n\n---", "meal_ideas": "Stirred into Greek yogurt overnight \u00b7 Added to oats (overnight chia-oat pudding) \u00b7 Mixed into a smoothie \u00b7 Sprinkled over a salad \u00b7 Soaked in almond milk as chia pudding\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]]\n\n---", "good_energy_relevance": "Chia seeds are the single most fibre-dense addition to the food library \u2014 2 tablespoons adds 8.3g fibre with almost no glucose impact. The mucilaginous gel directly slows gastric emptying and glucose absorption, making it a powerful glucose-blunting addition to any carbohydrate-containing meal. The omega-3:omega-6 ratio (~0.3:1) is the most favourable of any common plant food, actively countering the omega-6 overload that most people carry from seed oil consumption.\n\n**Good Energy daily targets contribution (per 24g / 2 tbsp):**\n- Fibre: 8.3g of 50g target (17%)\n- Omega-3: 4,279mg ALA (converts to ~200\u2013400mg EPA/DHA)\n- Antioxidants: moderate (quercetin, kaempferol, chlorogenic acid)\n- Probiotics: none (but soluble fibre is a highly effective prebiotic)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Chicken Breast', 'protein', 165, 31.0, 0, 3.6, 0, 60, false, '{"content_hash": "b9da199ea2e92f1726e0ef70d350ca15", "portion_state": "cooked", "quotes": ["Lean protein is the foundation of every body composition goal \u2014 it preserves muscle, drives satiety, and costs almost nothing in fat or carbohydrate."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **Complete protein** \u00b7 **2.47g leucine / 100g** \u00b7 **GI: 0** \u00b7 **Mitochondrial benefit: High**\n The highest-leucine common food and the most efficient lean protein for hitting daily targets without overshooting calories.", "tags": 0, "food_category": "protein", "calories_per_100g": 165, "protein_per_100g": 31.0, "carbs_per_100g": 0.0, "sugar_per_100g": 0.0, "added_sugar": false, "fat_per_100g": 3.6, "saturated_fat_per_100g": 1.0, "fibre_per_100g": 0.0, "cholesterol_per_100g": 85, "omega3_per_100g_mg": 60, "iron_per_100g": 0.7, "zinc_per_100g": 1.0, "magnesium_per_100g": 29, "potassium_per_100g": 256, "sodium_per_100g": 74, "selenium_per_100g_\u00b5g": 27, "choline_per_100g_mg": 85, "vitamin_c_per_100g_mg": 0, "vitamin_d_per_100g_iu": 4, "vitamin_b12_per_100g_\u00b5g": 0.3, "complete_protein": true, "leucine_per_100g": 2.47, "antioxidant_level": "low", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "g", "serving_unit_g": 1, "typical_serving": "150g cooked", "typical_serving_g": 150, "glycaemic_index": 0, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "100g", "calories": "165", "protein": "31.0g", "fat": "3.6g"}, {"portion": "150g", "calories": "248", "protein": "46.5g", "fat": "5.4g"}, {"portion": "200g", "calories": "330", "protein": "62.0g", "fat": "7.2g"}, {"portion": "250g", "calories": "413", "protein": "77.5g", "fat": "9.0g"}], "food_synergies": [{"paired_with": "Leucine", "synergy": "2.47g", "mechanism": "Highest of common foods \u2014 primary mTOR trigger for MPS"}, {"paired_with": "Lysine", "synergy": "2.67g", "mechanism": "Collagen synthesis; carnitine production"}, {"paired_with": "Isoleucine", "synergy": "1.43g", "mechanism": "BCAA; glucose uptake into muscle during exercise"}, {"paired_with": "Valine", "synergy": "1.49g", "mechanism": "BCAA; muscle glycogen sparing"}, {"paired_with": "Threonine", "synergy": "1.35g", "mechanism": "Collagen and elastin; immune function"}, {"paired_with": "Phenylalanine", "synergy": "1.26g", "mechanism": "Tyrosine \u2192 dopamine, adrenaline, thyroid hormones"}, {"paired_with": "Methionine", "synergy": "0.89g", "mechanism": "Glutathione synthesis; SAMe for methylation"}, {"paired_with": "Tryptophan", "synergy": "0.38g", "mechanism": "Serotonin precursor; sleep regulation"}, {"paired_with": "Histidine", "synergy": "0.96g", "mechanism": "Carnosine synthesis; intramuscular buffering"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Satiety + vitamin absorption", "mechanism": "Avocado''s fat slows gastric emptying, extending satiety from lean protein; monounsaturated fat also carries fat-soluble vitamins and potassium supports muscle recovery"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Antioxidant cover", "mechanism": "High protein throughput generates oxidative byproducts; anthocyanins counteract exercise-induced oxidative stress alongside protein-driven tissue repair"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Complementary fat profile", "mechanism": "Alternating chicken (very high leucine, lean) and salmon (omega-3 rich) across the week provides complementary nutrients neither delivers alone"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Nutrient timing pair", "mechanism": "Oats 2\u20133 hours pre-training for sustained glycogen; chicken post-training for MPS \u2014 the classic nutrient timing combination"}], "dosage_and_timing_guidance": "> [!info] How much per meal and per day?\n> **Optimal per meal: 150\u2013200g cooked** \u2014 provides 46\u201362g protein and clears the leucine threshold reliably\n>\n> **Diminishing returns above 300g per sitting:** muscle protein synthesis does not scale linearly with protein dose; the excess is oxidised for energy or converted to urea, not converted to muscle tissue. Two moderate meals are more effective than one very large serving.\n>\n> **Weekly variety:** chicken should not be the only protein source. Aim for 2\u20133 salmon servings per week for omega-3 balance \u2014 chicken provides almost none (60mg/100g vs. salmon''s 1,800mg). Eggs complement chicken by adding choline and fat-soluble vitamins that chicken lacks.\n>\n> **No cholesterol concern:** 85mg per 100g is low relative to eggs (372mg/100g); chicken breast is one of the most lipid-benign protein sources available.\n\n---", "meal_ideas": "Grilled with avocado and a green salad \u00b7 Sliced over spinach with olive oil and lemon \u00b7 Meal-prepped in bulk for the week \u00b7 Post-training with blueberries\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]]\n\n---", "good_energy_relevance": "Zero glycaemic impact. High protein density supports muscle protein synthesis after resistance training \u2014 muscle is the primary tissue for glucose disposal, making lean mass directly protective against insulin resistance. The niacin content makes chicken breast one of the best dietary sources of NAD+ precursors.\n\n**Good Energy daily targets contribution (per 150g):**\n- Fibre: 0g of 50g target\n- Omega-3: 90mg of 2,000mg target\n- Antioxidants: low\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
