insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Cottage Cheese', 'protein', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "439d364c3557b6e6228fef299d9475cd", "portion_state": "unspecified", "quotes": ["calories_per_unit: 180\nprotein_per_unit_g: 28\ncarbs_per_unit_g: 14\nfat_per_unit_g: 5\nfiber_per_unit_g: 0\nsugar_per_unit_g: 8\ncholesterol_per_unit_mg: 30\nprocessing_level:"], "nutrient": "Amount", "calcium": 250, "iron": 0.2, "potassium": 200, "sodium": 880, "tags": 0, "food_category": "protein", "source": "notion", "notion_category": "Protein", "serving_unit": "1 cup", "calories_per_unit": 180, "protein_per_unit_g": 28, "carbs_per_unit_g": 14, "fat_per_unit_g": 5, "fiber_per_unit_g": 0, "sugar_per_unit_g": 8, "cholesterol_per_unit_mg": 30, "processing_level": "Processed", "fermented": true}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Eggs', 'protein', 143, 12.6, 0.7, 9.5, 0, 180, false, '{"content_hash": "d11927e68e42d1554ab81ef379312404", "portion_state": "unspecified", "quotes": ["The egg is the most complete food nature produces \u2014 every amino acid, every fat-soluble vitamin, and choline for the brain."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **Complete protein** \u00b7 **1.09g leucine / 100g** \u00b7 **GI: 0** \u00b7 **Mitochondrial benefit: High**\n The most complete whole food available \u2014 every essential amino acid, four fat-soluble vitamins, and the richest dietary source of choline.", "tags": 0, "food_category": "protein", "calories_per_100g": 143, "protein_per_100g": 12.6, "carbs_per_100g": 0.7, "sugar_per_100g": 0.4, "added_sugar": false, "fat_per_100g": 9.5, "saturated_fat_per_100g": 3.1, "fibre_per_100g": 0.0, "cholesterol_per_100g": 372, "omega3_per_100g_mg": 180, "iron_per_100g": 1.8, "zinc_per_100g": 1.3, "magnesium_per_100g": 12, "potassium_per_100g": 138, "sodium_per_100g": 142, "selenium_per_100g_\u00b5g": 30, "choline_per_100g_mg": 294, "vitamin_c_per_100g_mg": 0, "vitamin_d_per_100g_iu": 82, "vitamin_b12_per_100g_\u00b5g": 1.4, "complete_protein": true, "leucine_per_100g": 1.09, "antioxidant_level": "moderate", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "egg", "serving_unit_g": 50, "typical_serving": "2 eggs", "typical_serving_g": 100, "glycaemic_index": 0, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "1 egg (50g)", "calories": "72", "protein": "6.3g", "fat": "4.8g"}, {"portion": "2 eggs (100g)", "calories": "143", "protein": "12.6g", "fat": "9.5g"}, {"portion": "3 eggs (150g)", "calories": "215", "protein": "18.9g", "fat": "14.3g"}, {"portion": "4 eggs (200g)", "calories": "286", "protein": "25.2g", "fat": "19.0g"}], "food_synergies": [{"paired_with": "Leucine", "synergy": "1.09g", "mechanism": "Primary mTOR activator \u2014 triggers muscle protein synthesis"}, {"paired_with": "Lysine", "synergy": "0.91g", "mechanism": "Collagen synthesis; carnitine production for fat metabolism"}, {"paired_with": "Phenylalanine", "synergy": "0.68g", "mechanism": "Precursor to dopamine, adrenaline, and thyroid hormones"}, {"paired_with": "Valine", "synergy": "0.77g", "mechanism": "BCAA; muscle glycogen sparing during endurance work"}, {"paired_with": "Threonine", "synergy": "0.56g", "mechanism": "Immune function; collagen and elastin production"}, {"paired_with": "Isoleucine", "synergy": "0.54g", "mechanism": "BCAA; glucose uptake into muscle during exercise"}, {"paired_with": "Histidine", "synergy": "0.30g", "mechanism": "Carnosine synthesis; intramuscular acid buffering"}, {"paired_with": "Methionine", "synergy": "0.38g", "mechanism": "Glutathione synthesis; methylation reactions"}, {"paired_with": "Tryptophan", "synergy": "0.17g", "mechanism": "Serotonin precursor; sleep quality regulation"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Glucose blunting", "mechanism": "Egg fat and protein slows gastric emptying \u2014 significantly reduces the glucose spike from oat carbohydrates when eaten first or together"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble vitamin absorption", "mechanism": "Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 co-ingestion substantially improves absorption"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Choline + DHA synergy", "mechanism": "Dietary choline and DHA combine to form phosphatidylcholine \u2014 the primary structural phospholipid of mitochondrial and neuronal membranes; eating both maximises substrate availability"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Antioxidant cover for training recovery", "mechanism": "Anthocyanins reduce exercise-induced oxidative stress while egg protein drives tissue repair \u2014 an effective post-training pairing"}], "dosage_and_timing_guidance": "> [!warning] Cholesterol \u2014 the nuanced picture\n> One large egg contains **~186mg dietary cholesterol** \u2014 historically flagged under the old <300mg/day guideline.\n>\n> The current picture is more nuanced:\n> - **~75% of people are hypo-responders** \u2014 dietary cholesterol has minimal effect on their LDL; the liver compensates by producing less of its own\n> - **~25% of people are hyper-responders** \u2014 dietary cholesterol does raise LDL meaningfully; if this is you, eggs warrant closer monitoring\n> - The 2020 US Dietary Guidelines removed the specific 300mg/day cap, acknowledging individual variation\n> - **Saturated fat is a bigger LDL driver than dietary cholesterol** for most people \u2014 and eggs are moderate in saturated fat (3.1g/100g)\n>\n> **Practical range for active individuals: 2\u20134 whole eggs per day** is well-supported in the literature for metabolically healthy people. Monitor LDL particle size (not just total LDL) and HDL if eating at the higher end \u2014 eggs tend to raise both, and the ratio often does not worsen.\n\n---", "meal_ideas": "Scrambled or poached in olive oil \u00b7 Hard-boiled as a portable snack \u00b7 3 eggs with 60g oats and blueberries at breakfast (~29g protein, improved leucine threshold when paired with another protein)\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]]\n\n---", "good_energy_relevance": "Near-zero glycaemic impact. The fat and protein combination maximises satiety and slows gastric emptying, blunting the glucose spike from any carbohydrates eaten at the same meal. Choline is a structural component of cardiolipin \u2014 the phospholipid central to the inner mitochondrial membrane and efficient ATP production.\n\n**Good Energy daily targets contribution (per 2 eggs):**\n- Fibre: 0g of 50g target\n- Omega-3: 180mg of 2,000mg target\n- Antioxidants: moderate (lutein, zeaxanthin, selenium)\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Flaxseeds (Ground)', 'fat', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "5d276c93a3e380e811c01f8d30fe00d2", "portion_state": "unspecified", "quotes": ["calories_per_unit: 90\nprotein_per_unit_g: 3\ncarbs_per_unit_g: 4\nfat_per_unit_g: 7\nsugar_per_unit_g: 0\nprocessing_level:"], "nutrient": "Amount", "calcium": 50, "iron": 0.75, "potassium": 125, "sodium": 0, "tags": 0, "food_category": "fat", "source": "notion", "notion_category": "Fat", "serving_unit": "2 tbsp", "calories_per_unit": 90, "protein_per_unit_g": 3, "carbs_per_unit_g": 4, "fat_per_unit_g": 7, "sugar_per_unit_g": 0, "processing_level": "Minimally Processed", "fermented": false}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Greek Yogurt', 'fermented-protein', 97, 9.0, 3.6, 5.0, 0, 50, false, '{"content_hash": "a578aa7b2b5cf7152c24f450ce48c2d1", "portion_state": "unspecified", "quotes": ["Fermented foods are one of the most direct ways to replenish and diversify the gut microbiome \u2014 and the microbiome is the foundation of metabolic and immune health."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **Probiotic: Yes** \u00b7 **Complete protein** \u00b7 **GI: 11** \u00b7 **Mitochondrial benefit: Moderate**\n One of the most practical daily probiotic sources \u2014 and a concentrated protein that doubles as gut-microbiome fuel.", "tags": 0, "food_category": "fermented-protein", "calories_per_100g": 97, "protein_per_100g": 9.0, "carbs_per_100g": 3.6, "sugar_per_100g": 3.2, "added_sugar": false, "fat_per_100g": 5.0, "saturated_fat_per_100g": 3.2, "fibre_per_100g": 0.0, "cholesterol_per_100g": 17, "omega3_per_100g_mg": 50, "iron_per_100g": 0.1, "zinc_per_100g": 0.6, "magnesium_per_100g": 11, "potassium_per_100g": 141, "sodium_per_100g": 36, "selenium_per_100g_\u00b5g": 9.7, "choline_per_100g_mg": 15, "vitamin_c_per_100g_mg": 0, "vitamin_d_per_100g_iu": 0, "vitamin_b12_per_100g_\u00b5g": 0.75, "complete_protein": true, "leucine_per_100g": 0.9, "antioxidant_level": "low", "probiotic": true, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "g", "serving_unit_g": 1, "typical_serving": "200g", "typical_serving_g": 200, "glycaemic_index": 11, "mitochondrial_benefit": "moderate", "quick_reference_servings": [{"portion": "100g", "calories": "97", "protein": "9.0g", "fat": "5.0g"}, {"portion": "150g", "calories": "146", "protein": "13.5g", "fat": "7.5g"}, {"portion": "200g (typical bowl)", "calories": "194", "protein": "18.0g", "fat": "10.0g"}, {"portion": "250g", "calories": "243", "protein": "22.5g", "fat": "12.5g"}], "food_synergies": [{"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries", "synergy": "Probiotic + prebiotic (synbiotic)", "mechanism": "Blueberry polyphenols act as prebiotics \u2014 selectively feeding the Lactobacillus and Bifidobacterium strains in the yogurt; this combination (probiotic + prebiotic = synbiotic) is more effective than either alone"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chia Seeds", "synergy": "Fibre + probiotic", "mechanism": "Chia seeds provide soluble fibre that feeds the probiotic cultures and slows the digestion of yogurt''s carbohydrates; also dramatically increases the satiety of the meal"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Prebiotic fibre amplification", "mechanism": "Beta-glucan from oats is one of the most effective prebiotic fibres for Lactobacillus and Bifidobacterium; mixing with yogurt creates a gut-optimised breakfast"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Walnuts", "synergy": "Polyphenol + probiotic", "mechanism": "Walnut polyphenols (ellagic acid) are metabolised by gut bacteria into urolithins \u2014 compounds with anti-inflammatory and mitochondrial effects only accessible via a healthy microbiome"}], "dosage_and_timing_guidance": "> [!info] Daily probiotic servings\n> **Optimal: 150\u2013200g per serving; 1\u20132 servings per day**\n>\n> Casey Means recommends 3+ servings of fermented foods daily. Greek yogurt can cover 1\u20132 of these if eaten at breakfast and as a snack; the remainder can come from kimchi, sauerkraut, or kefir.\n>\n> **Lactose intolerance:** the straining process and fermentation reduce lactose content to ~3.2g per 100g (vs. 4.8g in regular milk). Many people with mild lactose intolerance tolerate Greek yogurt well. Severely intolerant individuals should trial a small portion first.\n>\n> **Upper limit:** no meaningful upper limit for metabolically healthy individuals. Large amounts (400g+) in one sitting add significant saturated fat and calories \u2014 spread across the day is more effective than one large dose for microbiome diversity.\n\n---", "meal_ideas": "Plain with blueberries and chia seeds \u00b7 Layered with oats as overnight \"yogurt oats\" \u00b7 Post-training protein source \u00b7 As a base for dressings in place of mayonnaise\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chia Seeds]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Walnuts]]\n\n---", "good_energy_relevance": "The gut microbiome is the fourth root cause of metabolic dysfunction in the Good Energy framework (gut dysbiosis). Greek yogurt directly addresses this \u2014 the live cultures populate the gut, produce short-chain fatty acids (SCFAs), and improve the intestinal barrier that prevents endotoxins from triggering systemic inflammation. B12 supports mitochondrial energy production, and the low GI (11) means it causes almost no glucose perturbation.\n\n**Good Energy daily targets contribution (per 200g):**\n- Fibre: 0g of 50g target\n- Omega-3: 100mg of 2,000mg target\n- Antioxidants: low\n- Probiotics: \u2713 1 of 3 daily probiotic servings\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
