insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Kirkland Three Berry Blend', 'fruit', 52, 1.1, 12.0, 0.5, 3.5, 90, false, '{"content_hash": "8ba18cbe6b5235cd223f21e6870c12cc", "portion_state": "unspecified", "quotes": ["Variety in polyphenol sources is not a minor detail \u2014 different anthocyanins activate different antioxidant pathways. A mix of berries covers more biological ground than the same dose of one berry."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **Three-berry anthocyanin spectrum** \u00b7 **3.5g fibre / 100g** \u00b7 **18mg vitamin C / 100g** \u00b7 **Mitochondrial benefit: High**\n A broader polyphenol profile than any single berry \u2014 and a practical Costco staple that stays nutritious frozen year-round.", "tags": 0, "food_category": "fruit", "brand": "Kirkland Signature", "costco_product": true, "product_name": "Kirkland Signature Three Berry Blend", "berry_composition": "blueberries, blackberries, raspberries", "calories_per_100g": 52, "protein_per_100g": 1.1, "carbs_per_100g": 12.0, "sugar_per_100g": 7.5, "added_sugar": false, "fat_per_100g": 0.5, "saturated_fat_per_100g": 0.0, "fibre_per_100g": 3.5, "cholesterol_per_100g": 0, "omega3_per_100g_mg": 90, "iron_per_100g": 0.5, "zinc_per_100g": 0.2, "magnesium_per_100g": 12, "potassium_per_100g": 130, "sodium_per_100g": 1, "selenium_per_100g_\u00b5g": 0.2, "choline_per_100g_mg": 8, "vitamin_c_per_100g_mg": 18, "vitamin_d_per_100g_iu": 0, "vitamin_b12_per_100g_\u00b5g": 0, "complete_protein": false, "leucine_per_100g": 0.06, "antioxidant_level": "high", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "g", "serving_unit_g": 1, "typical_serving": "80g", "typical_serving_g": 80, "glycaemic_index": 45, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "80g", "calories": "42", "protein": "9.6g", "fat": "6.0g"}, {"portion": "120g", "calories": "62", "protein": "14.4g", "fat": "9.0g"}, {"portion": "150g", "calories": "78", "protein": "18.0g", "fat": "11.3g"}], "food_synergies": [{"paired_with": "Berry", "synergy": "Primary Polyphenols", "mechanism": "Key Action"}, {"paired_with": "Blueberries", "synergy": "Delphinidin, cyanidin, petunidin, peonidin, malvidin glucosides", "mechanism": "PGC-1\u03b1 activation \u2192 mitochondrial biogenesis; crosses blood-brain barrier"}, {"paired_with": "Blackberries", "synergy": "Cyanidin-3-glucoside (highest of the three)", "mechanism": "Anti-inflammatory; neuroprotective; cardiovascular protection"}, {"paired_with": "Raspberries", "synergy": "Ellagic acid, raspberry ketones, quercetin", "mechanism": "Ellagic acid \u2192 urolithins (gut bacteria convert to mitochondrial activators); anti-inflammatory"}, {"paired_with": "Attribute", "synergy": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] (100g)", "mechanism": "Three Berry Blend (100g)"}, {"paired_with": "Calories", "synergy": "57", "mechanism": "52"}, {"paired_with": "Fibre", "synergy": "2.4g", "mechanism": "3.5g"}, {"paired_with": "Vitamin C", "synergy": "9.7mg", "mechanism": "18mg"}, {"paired_with": "Anthocyanins", "synergy": "~165mg", "mechanism": "~200\u2013250mg (estimated)"}, {"paired_with": "GI", "synergy": "53", "mechanism": "45 (lower \u2014 blackberries and raspberries have lower GI)"}, {"paired_with": "Polyphenol diversity", "synergy": "Moderate", "mechanism": "High (three distinct profiles)"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt", "synergy": "Synbiotic + polyphenol diversity", "mechanism": "Probiotic bacteria from yogurt convert raspberry ellagic acid into urolithins; the three-berry polyphenol mix selectively feeds more diverse microbial populations than a single berry"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats", "synergy": "Double anti-glycaemic", "mechanism": "Beta-glucan + combined berry anthocyanins; lower GI than oats + blueberries alone"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble phytonutrient absorption", "mechanism": "Avocado fat enhances absorption of fat-soluble carotenoids and polyphenols from all three berries"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chia Seeds", "synergy": "Fibre amplification + antioxidant cover", "mechanism": "Combined fibre exceeds 7g per serving \u2014 significant prebiotic dose; chia ALA + berry polyphenols are complementary anti-inflammatory inputs"}], "dosage_and_timing_guidance": "> [!info] Same practical range as pure blueberries\n> **Optimal: 80\u2013150g per day**\n> - 80g delivers ~2.8g fibre, ~14mg vitamin C, and a meaningful polyphenol dose\n> - 120\u2013150g is appropriate when the blend is the primary fruit source for the day\n>\n> **Frozen from frozen:** no need to thaw before eating \u2014 frozen berries can be added directly to oats, yogurt, or a smoothie. Thawed berries soften quickly; use promptly after thawing.\n>\n> **No upper limit concern** for metabolically healthy individuals. Natural sugars (7.5g/100g) are well-buffered by fibre and the anti-glycaemic effects of the polyphenols.\n\n---", "meal_ideas": "Straight from frozen into Greek yogurt \u00b7 Added to oats \u00b7 Blended into a smoothie \u00b7 Thawed as a topping with chia seeds\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Greek Yogurt]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chia Seeds]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]]", "good_energy_relevance": "The three-berry blend covers more polyphenol pathways simultaneously than any single berry \u2014 addressing the antioxidant attribute of the Good Energy framework more broadly. The ellagic acid from raspberries adds a urolithin production pathway (via gut bacteria) that pure blueberries do not provide. As a Costco staple kept frozen, it is one of the most practical high-antioxidant foods to have consistently on hand.\n\n**Good Energy daily targets contribution (per 80g):**\n- Fibre: 2.8g of 50g target (6%)\n- Omega-3: 72mg of 2,000mg target (trace ALA)\n- Antioxidants: high (multi-spectrum anthocyanins, ellagic acid, quercetin)\n- Probiotics: none (but polyphenols are prebiotics for diverse microbial populations)\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
