insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Salmon', 'Protein', 206, 20.4, 0, 13.4, 0, 1800, false, '{"content_hash": "8c8866519baa883573c5a3b601d106f4", "portion_state": "cooked", "quotes": ["Wild salmon is the most mitochondrially supportive food available \u2014 omega-3s are literally built into the membranes of every mitochondrion in your body."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **Complete protein** \u00b7 **1,800mg omega-3 / 100g** \u00b7 **GI: 0** \u00b7 **Mitochondrial benefit: High**\n The highest-priority food for mitochondrial membrane integrity \u2014 EPA and DHA are literally built into every mitochondrion in the body.", "food_category": "Protein", "calories_per_100g": 206, "protein_per_100g": 20.4, "carbs_per_100g": 0, "fat_per_100g": 13.4, "saturated_fat_per_100g": 3.1, "fibre_per_100g": 0, "cholesterol": 63, "omega-3_epadha": 1800, "glycaemic_index": 0, "seed_oil": false, "vitamin_d": 526, "vitamin_b12": 2.8, "selenium": 30, "choline": 94, "potassium": 363, "magnesium": 29, "iron": 0.8, "zinc": 0.6, "complete_protein": true, "leucine_per_100g": 1.61, "antioxidant_level": "High (Astaxanthin)", "mitochondrial_benefit": "High", "target_body_systems": "Brain, Heart, Muscles, Eyes, Mitochondria, Immune, Skin", "food_synergies": [{"paired_with": "Avocado", "synergy": "Anti-inflammatory fat synergy", "mechanism": "Monounsaturated fat (avocado) + EPA/DHA (salmon) together cover the full anti-inflammatory lipid spectrum; zero glucose impact meal"}, {"paired_with": "Eggs", "synergy": "Choline + DHA synergy", "mechanism": "Choline (eggs) and DHA (salmon) are co-substrates for phosphatidylcholine synthesis"}, {"paired_with": "Blueberries", "synergy": "Dual antioxidant protection", "mechanism": "Astaxanthin (salmon) + anthocyanins (blueberries) act through different antioxidant pathways simultaneously"}, {"paired_with": "Lemon / vitamin C", "synergy": "Iron absorption", "mechanism": "Vitamin C enhances non-heme iron absorption from salmon"}], "dosage_and_timing_guidance": "> [!info] Weekly target and practical considerations\n> **Target: 2\u20133 servings per week (150\u2013200g each)**\n> - 2 servings/week = ~5,400mg EPA+DHA \u2014 covers the 2,000mg/day average across the week\n> - 3 servings/week provides additional vitamin D and astaxanthin benefits\n>\n> **Mercury:** Atlantic salmon has naturally low mercury compared to larger fish (tuna, swordfish).\n> **Wild vs. farmed:** Wild-caught salmon has higher omega-3 content (~2,500mg/100g vs. ~1,800mg farmed) and significantly more astaxanthin.\n\n---", "good_energy_relevance": "Zero glycemic impact. The EPA and DHA in salmon directly integrate into mitochondrial membranes, improving the efficiency and structural integrity of the electron transport chain. Omega-3s also reduce chronic inflammation in the Good Energy framework.\n\n**Good Energy daily targets contribution (per 150g):**\n- Fibre: 0g of 50g target\n- Omega-3: 2,700mg of 2,000mg target \u2713 (covers daily target in one serving)\n- Antioxidants: high (astaxanthin, selenium, vitamin D)\n- Probiotics: none"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Sauerkraut (Wildbrine)', 'produce', 0, 0, 0, 0, 0, 0, false, '{"content_hash": "a9c13d26c9c318671c279a6870427f85", "portion_state": "unspecified", "quotes": ["calories_per_unit: 10\nprotein_per_unit_g: 0.4\ncarbs_per_unit_g: 2\nfat_per_unit_g: 0\nfiber_per_unit_g: 1\nsugar_per_unit_g: 1\nprocessing_level:"], "nutrient": "Amount", "calcium": 10, "iron": 0.1, "potassium": 50, "sodium": 260, "tags": 0, "food_category": "produce", "source": "notion", "notion_category": "Produce", "serving_unit": "2 tbsp", "calories_per_unit": 10, "protein_per_unit_g": 0.4, "carbs_per_unit_g": 2, "fat_per_unit_g": 0, "fiber_per_unit_g": 1, "sugar_per_unit_g": 1, "processing_level": "Minimally Processed", "fermented": true}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Spinach', 'vegetable', 23, 2.9, 3.6, 0.4, 2.2, 138, false, '{"content_hash": "5ad815f5a44ddb43e59e564c749f35a2", "portion_state": "cooked", "quotes": ["Dark leafy greens are the most nutrient-dense category of food on the planet \u2014 more vitamins, minerals, and phytonutrients per calorie than any other food group."], "sports_nutrition_snapshot": "Sports Nutrition Snapshot\n **12,198\u00b5g lutein+zeaxanthin / 100g** \u00b7 **79mg magnesium / 100g** \u00b7 **GI: 15** \u00b7 **Mitochondrial benefit: High**\n The most micronutrient-dense leafy green \u2014 and one of the richest plant sources of magnesium, the mineral most critical for ATP production.", "tags": 0, "food_category": "vegetable", "calories_per_100g": 23, "protein_per_100g": 2.9, "carbs_per_100g": 3.6, "sugar_per_100g": 0.4, "added_sugar": false, "fat_per_100g": 0.4, "saturated_fat_per_100g": 0.1, "fibre_per_100g": 2.2, "cholesterol_per_100g": 0, "omega3_per_100g_mg": 138, "iron_per_100g": 2.7, "zinc_per_100g": 0.5, "magnesium_per_100g": 79, "potassium_per_100g": 558, "sodium_per_100g": 79, "selenium_per_100g_\u00b5g": 1.0, "choline_per_100g_mg": 19, "vitamin_c_per_100g_mg": 28.1, "vitamin_d_per_100g_iu": 0, "vitamin_b12_per_100g_\u00b5g": 0, "complete_protein": false, "leucine_per_100g": 0.22, "antioxidant_level": "high", "probiotic": false, "refined": false, "seed_oil": false, "body_systems": 0, "serving_unit": "g", "serving_unit_g": 1, "typical_serving": "60g raw", "typical_serving_g": 60, "glycaemic_index": 15, "mitochondrial_benefit": "high", "quick_reference_servings": [{"portion": "30g (side handful)", "calories": "7", "protein": "24mg", "fat": "58\u00b5g"}, {"portion": "60g (large handful)", "calories": "14", "protein": "47mg", "fat": "116\u00b5g"}, {"portion": "100g", "calories": "23", "protein": "79mg", "fat": "194\u00b5g"}, {"portion": "150g (cooked portion)", "calories": "35", "protein": "119mg", "fat": "291\u00b5g"}], "food_synergies": [{"paired_with": "Compound", "synergy": "Per 100g", "mechanism": "Key Actions"}, {"paired_with": "Lutein + Zeaxanthin", "synergy": "12,198\u00b5g", "mechanism": "Concentrates in the macula; protects retinal cells from oxidative damage; highest concentration of any common food"}, {"paired_with": "Beta-carotene", "synergy": "5,626\u00b5g", "mechanism": "Provitamin A; antioxidant; anti-inflammatory"}, {"paired_with": "Coenzyme Q10 (CoQ10)", "synergy": "trace\u20130.9mg", "mechanism": "Direct mitochondrial electron transport cofactor; rare in plant foods; regenerates vitamin E"}, {"paired_with": "Quercetin", "synergy": "~13mg", "mechanism": "Anti-inflammatory; antiviral; mast cell stabiliser"}, {"paired_with": "Kaempferol", "synergy": "~8mg", "mechanism": "Anti-inflammatory; antiproliferative; heart protective"}, {"paired_with": "Chlorophyll", "synergy": "high", "mechanism": "Antioxidant; may bind dietary mutagens; liver protective"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon", "synergy": "Iron absorption + omega-3", "mechanism": "Vitamin C in spinach enhances non-heme iron absorption; omega-3 from salmon reduces the inflammation that impairs iron utilisation"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs", "synergy": "Fat-soluble nutrient absorption", "mechanism": "Egg fat acts as a carrier for spinach''s fat-soluble compounds (lutein, zeaxanthin, beta-carotene, vitamin K, vitamin E) \u2014 absorption increases substantially when fat is co-ingested"}, {"paired_with": "\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado", "synergy": "Fat-soluble phytonutrient absorption", "mechanism": "Same mechanism as eggs \u2014 avocado fat is an excellent carrier for spinach carotenoids; this is one of the most evidence-backed food pairings in the carotenoid bioavailability literature"}, {"paired_with": "Lemon juice", "synergy": "Iron absorption", "mechanism": "Vitamin C from lemon directly chelates non-heme iron, converting it to the ferrous form that absorbs 2\u20133\u00d7 more efficiently"}], "dosage_and_timing_guidance": "> [!info] How much and in what form?\n> **Optimal: 60\u2013150g raw daily** (or equivalent cooked \u2014 roughly 10\u201320g cooked)\n>\n> Spinach is effectively a free food from a calorie standpoint (23 cal/100g). There is no practical upper limit for healthy individuals without kidney issues.\n>\n> **Kidney stones / oxalates:** people with a history of calcium-oxalate kidney stones should moderate raw spinach intake. Cooking significantly reduces oxalate content \u2014 cooked spinach is preferable in this case.\n>\n> **Vitamin K and anticoagulants (warfarin):** very high vitamin K intake (483\u00b5g/100g) can interfere with warfarin dosing. Consistent intake (same amount daily) is preferable to large fluctuations.\n>\n> **Raw vs. cooked:** raw spinach preserves vitamin C and folate (heat-sensitive); cooked spinach reduces oxalates and makes lutein, zeaxanthin, and beta-carotene more bioavailable (heat breaks down cell walls). Both are valuable \u2014 variety is ideal.\n\n---", "meal_ideas": "Raw in a salad with salmon, avocado, and lemon \u00b7 Wilted in olive oil as a side \u00b7 Blended into a smoothie (flavour is masked by fruit) \u00b7 Base layer under eggs\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]]\n\n---", "good_energy_relevance": "Spinach is one of the most micronutrient-dense foods available \u2014 the core of Means'' first trackable attribute. The magnesium content directly supports ATP production (the mitochondrial function target); the folate supports DNA methylation; the lutein and zeaxanthin protect mitochondrial membranes from oxidative damage. As a near-zero-calorie food with negligible glucose impact, it can be added to almost any meal without disrupting macronutrient targets.\n\n**Good Energy daily targets contribution (per 60g raw):**\n- Fibre: 1.3g of 50g target\n- Omega-3: 83mg of 2,000mg target (ALA, minimal)\n- Antioxidants: high (lutein/zeaxanthin, beta-carotene, quercetin, CoQ10)\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
